from AlgorithmImports import *

class ParallelTwoSlotStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily, Market.USA, False).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily, Market.USA, False).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily, Market.USA, False).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily, Market.USA, False).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily, Market.USA, False).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_closes = RollingWindow[float](2)
        self.spy_sma_values = RollingWindow[float](2)
        self.aapl_closes = RollingWindow[float](4)

        self.aapl_red_streak = 0
        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        self._update_market_state(data)

        if self.IsWarmingUp:
            return

        if not self._all_bars_present(data):
            return

        if not self._rules_ready():
            return

        if self.strategy_a_lot > 0 and self._spy_crosses_below_sma():
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and float(self.aapl_rsi.Current.Value) > 60.0:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and self._spy_crosses_above_sma():
            shares = int(
                0.40 * float(self.Portfolio.TotalPortfolioValue)
                / self.spy_closes[0]
            )
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.strategy_a_lot = shares

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000.0:
                shares = int(20_000.0 / self.aapl_closes[0])
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_lot = shares

    def _update_market_state(self, data):
        if data.Bars.ContainsKey(self.spy):
            bar = data.Bars[self.spy]
            self.spy_sma.Update(bar.EndTime, bar.Close)
            self.spy_closes.Add(float(bar.Close))

            if self.spy_sma.IsReady:
                self.spy_sma_values.Add(float(self.spy_sma.Current.Value))

        if data.Bars.ContainsKey(self.aapl):
            bar = data.Bars[self.aapl]
            close = float(bar.Close)

            self.aapl_rsi.Update(bar.EndTime, bar.Close)

            if self.aapl_closes.Count > 0:
                if close < self.aapl_closes[0]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_closes.Add(close)

    def _all_bars_present(self, data):
        for symbol in self.symbols:
            if not data.Bars.ContainsKey(symbol):
                return False
        return True

    def _rules_ready(self):
        return (
            self.spy_sma.IsReady
            and self.spy_closes.IsReady
            and self.spy_sma_values.IsReady
            and self.aapl_rsi.IsReady
            and self.aapl_closes.IsReady
        )

    def _spy_crosses_above_sma(self):
        return (
            self.spy_closes[1] <= self.spy_sma_values[1]
            and self.spy_closes[0] > self.spy_sma_values[0]
        )

    def _spy_crosses_below_sma(self):
        return (
            self.spy_closes[1] >= self.spy_sma_values[1]
            and self.spy_closes[0] < self.spy_sma_values[0]
        )

