from AlgorithmImports import *
from collections import deque


class TwoSlotPrivateLotAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self._spy = self.AddEquity("SPY", Resolution.Daily, Market.USA, False).Symbol
        self._aapl = self.AddEquity("AAPL", Resolution.Daily, Market.USA, False).Symbol
        self._ibm = self.AddEquity("IBM", Resolution.Daily, Market.USA, False).Symbol
        self._bac = self.AddEquity("BAC", Resolution.Daily, Market.USA, False).Symbol
        self._aig = self.AddEquity("AIG", Resolution.Daily, Market.USA, False).Symbol
        self._symbols = (self._spy, self._aapl, self._ibm, self._bac, self._aig)

        self._spy_sma = SimpleMovingAverage(100)
        self._spy_sma.Window.Size = 2
        self._spy_closes = deque(maxlen=2)

        self._aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self._aapl_previous_close = None
        self._aapl_red_streak = 0
        self._aapl_close_count = 0

        self._a_lot = 0
        self._b_lot = 0
        self._a_order_pending = False
        self._b_order_pending = False

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        bars = data.Bars

        if bars.ContainsKey(self._spy):
            spy_bar = bars[self._spy]
            self._spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            self._spy_closes.appendleft(spy_bar.Close)

        if bars.ContainsKey(self._aapl):
            aapl_bar = bars[self._aapl]
            aapl_close = aapl_bar.Close

            self._aapl_rsi.Update(aapl_bar.EndTime, aapl_close)
            self._aapl_close_count += 1

            if self._aapl_previous_close is None:
                self._aapl_red_streak = 0
            elif aapl_close < self._aapl_previous_close:
                self._aapl_red_streak += 1
            else:
                self._aapl_red_streak = 0

            self._aapl_previous_close = aapl_close

        self._sync_lots_to_holdings()

        if self.IsWarmingUp:
            return

        if not self._all_subscribed_bars_present(bars):
            return

        if not self._rules_ready():
            return

        # Sell phase
        if self._a_lot > 0 and not self._a_order_pending:
            if self._spy_crosses_below_sma():
                self._submit_a_order(-self._a_lot)

        if self._b_lot > 0 and not self._b_order_pending:
            if self._aapl_rsi.Current.Value > 60:
                self._submit_b_order(-self._b_lot)

        # Buy phase
        if self._a_lot == 0 and not self._a_order_pending:
            if self._spy_crosses_above_sma():
                spy_close = bars[self._spy].Close
                quantity = int((self.Portfolio.TotalPortfolioValue * 40 / 100) / spy_close)
                if quantity > 0:
                    self._submit_a_order(quantity)

        if self._b_lot == 0 and not self._b_order_pending:
            if self._aapl_red_streak >= 3:
                aapl_close = bars[self._aapl].Close
                available_cash = self.Portfolio.CashBook["USD"].Amount

                if available_cash >= 20000:
                    quantity = int(20000 / aapl_close)
                    if quantity > 0:
                        self._submit_b_order(quantity)

    def OnOrderEvent(self, order_event):
        if order_event.Symbol == self._spy:
            if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
                self._a_lot = max(0, self._a_lot + int(order_event.FillQuantity))

            if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                self._a_order_pending = False

        elif order_event.Symbol == self._aapl:
            if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
                self._b_lot = max(0, self._b_lot + int(order_event.FillQuantity))

            if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
                self._b_order_pending = False

    def _all_subscribed_bars_present(self, bars):
        for symbol in self._symbols:
            if not bars.ContainsKey(symbol):
                return False
        return True

    def _rules_ready(self):
        return (
            self._spy_sma.IsReady
            and self._spy_sma.Samples >= 101
            and self._spy_sma.Window.Count >= 2
            and len(self._spy_closes) >= 2
            and self._aapl_rsi.IsReady
            and self._aapl_close_count >= 4
        )

    def _spy_crosses_above_sma(self):
        return (
            self._spy_closes[1] <= self._spy_sma.Window[1].Value
            and self._spy_closes[0] > self._spy_sma.Current.Value
        )

    def _spy_crosses_below_sma(self):
        return (
            self._spy_closes[1] >= self._spy_sma.Window[1].Value
            and self._spy_closes[0] < self._spy_sma.Current.Value
        )

    def _sync_lots_to_holdings(self):
        self._a_lot = max(0, int(self.Portfolio[self._spy].Quantity))
        self._b_lot = max(0, int(self.Portfolio[self._aapl].Quantity))

    def _submit_a_order(self, quantity):
        self._a_order_pending = True
        ticket = self.MarketOrder(self._spy, quantity)

        if ticket.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            self._a_order_pending = False

    def _submit_b_order(self, quantity):
        self._b_order_pending = True
        ticket = self.MarketOrder(self._aapl, quantity)

        if ticket.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            self._b_order_pending = False

