from AlgorithmImports import *


class IndependentTwoSlotAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self._spy = self.AddEquity("SPY", Resolution.Daily, Market.USA, False).Symbol
        self._aapl = self.AddEquity("AAPL", Resolution.Daily, Market.USA, False).Symbol
        self._ibm = self.AddEquity("IBM", Resolution.Daily, Market.USA, False).Symbol
        self._bac = self.AddEquity("BAC", Resolution.Daily, Market.USA, False).Symbol
        self._aig = self.AddEquity("AIG", Resolution.Daily, Market.USA, False).Symbol
        self._symbols = [self._spy, self._aapl, self._ibm, self._bac, self._aig]

        self._spy_sma = SimpleMovingAverage(100)
        self._aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self._spy_last_close = None
        self._spy_previous_close = None
        self._spy_sma_value = None
        self._spy_previous_sma_value = None

        self._aapl_last_close = None
        self._aapl_red_streak = 0

        self._strategy_a_lot = 0
        self._strategy_b_lot = 0

    def _apply_split_adjustments(self, data):
        splits = data.Splits
        if splits is None:
            return

        if splits.ContainsKey(self._spy):
            split = splits[self._spy]
            if split.Type == SplitType.SplitOccurred and self._strategy_a_lot > 0:
                factor = float(split.SplitFactor)
                if factor > 0:
                    self._strategy_a_lot = int(round(self._strategy_a_lot / factor))

        if splits.ContainsKey(self._aapl):
            split = splits[self._aapl]
            if split.Type == SplitType.SplitOccurred and self._strategy_b_lot > 0:
                factor = float(split.SplitFactor)
                if factor > 0:
                    self._strategy_b_lot = int(round(self._strategy_b_lot / factor))

    def OnData(self, data):
        self._apply_split_adjustments(data)

        bars = data.Bars
        if bars is None:
            return

        if bars.ContainsKey(self._spy):
            spy_bar = bars[self._spy]
            self._spy_previous_close = self._spy_last_close
            self._spy_previous_sma_value = self._spy_sma_value

            self._spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            self._spy_last_close = spy_bar.Close
            self._spy_sma_value = (
                self._spy_sma.Current.Value if self._spy_sma.IsReady else None
            )

        if bars.ContainsKey(self._aapl):
            aapl_bar = bars[self._aapl]

            if (
                self._aapl_last_close is not None
                and aapl_bar.Close < self._aapl_last_close
            ):
                self._aapl_red_streak += 1
            else:
                self._aapl_red_streak = 0

            self._aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            self._aapl_last_close = aapl_bar.Close

        if not all(bars.ContainsKey(symbol) for symbol in self._symbols):
            return

        if (
            not self._spy_sma.IsReady
            or not self._aapl_rsi.IsReady
            or self._spy_previous_close is None
            or self._spy_previous_sma_value is None
        ):
            return

        spy_close = bars[self._spy].Close
        aapl_close = bars[self._aapl].Close

        spy_crosses_above = (
            self._spy_previous_close <= self._spy_previous_sma_value
            and spy_close > self._spy_sma_value
        )
        spy_crosses_below = (
            self._spy_previous_close >= self._spy_previous_sma_value
            and spy_close < self._spy_sma_value
        )

        if self._strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOrder(self._spy, -self._strategy_a_lot)
            self._strategy_a_lot = 0

        if self._strategy_b_lot > 0 and self._aapl_rsi.Current.Value > 60:
            self.MarketOrder(self._aapl, -self._strategy_b_lot)
            self._strategy_b_lot = 0

        if self._strategy_a_lot == 0 and spy_crosses_above:
            quantity = int(
                0.40 * float(self.Portfolio.TotalPortfolioValue) / float(spy_close)
            )
            if quantity > 0:
                self.MarketOrder(self._spy, quantity)
                self._strategy_a_lot = quantity

        if self._strategy_b_lot == 0 and self._aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000:
