from math import floor


class TwoSlotDailyStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily, Market.USA, False).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily, Market.USA, False).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily, Market.USA, False).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily, Market.USA, False).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily, Market.USA, False).Symbol
        self._symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self._spy_sma = SimpleMovingAverage(100)
        self._aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self._spy_closes = RollingWindow[float](2)
        self._spy_sma_values = RollingWindow[float](2)
        self._aapl_closes = RollingWindow[float](4)
        self._aapl_red_streak = 0

        self._strategy_a_lot = 0
        self._strategy_b_lot = 0

    def OnData(self, data):
        self._update_market_state(data)

        if not all(data.Bars.ContainsKey(symbol) for symbol in self._symbols):
            return

        if not self._rules_ready():
            return

        spy_crosses_above = (
            self._spy_closes[1] <= self._spy_sma_values[1]
            and self._spy_closes[0] > self._spy_sma_values[0]
        )
        spy_crosses_below = (
            self._spy_closes[1] >= self._spy_sma_values[1]
            and self._spy_closes[0] < self._spy_sma_values[0]
        )

        aapl_rsi_above_60 = float(self._aapl_rsi.Current.Value) > 60.0
        aapl_red_for_three_days = self._aapl_red_streak >= 3

        # Sells before buys.
        if self._strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self._strategy_a_lot)
            self._strategy_a_lot = 0

        if self._strategy_b_lot > 0 and aapl_rsi_above_60:
            self.MarketOrder(self.aapl, -self._strategy_b_lot)
            self._strategy_b_lot = 0

        if self._strategy_a_lot == 0 and spy_crosses_above:
            spy_close = float(data.Bars[self.spy].Close)
            if spy_close > 0:
                quantity = int(floor(
                    0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close
                ))
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self._strategy_a_lot = quantity

        if self._strategy_b_lot == 0 and aapl_red_for_three_days:
            aapl_close = float(data.Bars[self.aapl].Close)
            if float(self.Portfolio.Cash) >= 20_000 and aapl_close > 0:
                quantity = int(floor(20_000 / aapl_close))
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self._strategy_b_lot = quantity

    def _update_market_state(self, data):
        if data.Bars.ContainsKey(self.spy):
            bar = data.Bars[self.spy]
            self._spy_sma.Update(bar.EndTime, bar.Close)
            self._spy_closes.Add(float(bar.Close))

            if self._spy_sma.IsReady:
                self._spy_sma_values.Add(float(self._spy_sma.Current.Value))

        if data.Bars.ContainsKey(self.aapl):
            bar = data.Bars[self.aapl]
            close = float(bar.Close)

            if self._aapl_closes.Count > 0:
                if close < self._aapl_closes[0]:
                    self._aapl_red_streak += 1
                else:
                    self._aapl_red_streak = 0

            self._aapl_closes.Add(close)
            self._aapl_rsi.Update(bar.EndTime, bar.Close)

    def _rules_ready(self):
        return (
            self._spy_sma.IsReady
            and self._aapl_rsi.IsReady
            and self._spy_closes.IsReady
            and self._spy_sma_values.IsReady
            and self._aapl_closes.IsReady
        )

