        if self.IsWarmingUp or not self._all_bars_present(data):
            return

        if not self._rules_ready():
            return

        self._sync_private_lots()

        # Sells are evaluated before buys.
        if self._strategy_a_lot > 0 and self._spy_crosses_below_sma():
            self.MarketOrder(self._spy, -self._strategy_a_lot)
            self._strategy_a_lot = 0

        if self._strategy_b_lot > 0 and self._aapl_rsi.Current.Value > 60:
            self.MarketOrder(self._aapl, -self._strategy_b_lot)
            self._strategy_b_lot = 0

        if self._strategy_a_lot == 0 and self._spy_crosses_above_sma():
            close = float(data.Bars[self._spy].Close)
            if close > 0:
                quantity = int((float(self.Portfolio.TotalPortfolioValue) * 0.40) / close)
                if quantity > 0:
                    self.MarketOrder(self._spy, quantity)
                    self._strategy_a_lot = quantity

        if self._strategy_b_lot == 0 and self._aapl_red_streak >= 3:
            close = float(data.Bars[self._aapl].Close)
            if close > 0 and float(self.Portfolio.Cash) >= 20000:
