                if quantity > 0:
                    self.MarketOrder(self._aapl, quantity)
                    self._strategy_b_lot = quantity

    def _update_market_state(self, data):
        bars = data.Bars

        if bars.ContainsKey(self._spy):
            bar = bars[self._spy]
            close = float(bar.Close)

            self._spy_sma.Update(bar.EndTime, bar.Close)
            self._spy_samples += 1

            self._spy_closes.append(close)
            self._spy_sma_values.append(float(self._spy_sma.Current.Value))

            if len(self._spy_closes) > 2:
                self._spy_closes.pop(0)
            if len(self._spy_sma_values) > 2:
                self._spy_sma_values.pop(0)

        if bars.ContainsKey(self._aapl):
            bar = bars[self._aapl]
            close = float(bar.Close)

            if self._aapl_previous_close is not None:
                if close < self._aapl_previous_close:
                    self._aapl_red_streak += 1
                else:
                    self._aapl_red_streak = 0

            self._aapl_previous_close = close
            self._aapl_close_samples += 1
            self._aapl_rsi.Update(bar.EndTime, bar.Close)

    def _all_bars_present(self, data):
        return all(data.Bars.ContainsKey(symbol) for symbol in self._symbols)

    def _rules_ready(self):
        return (
            self._spy_sma.IsReady
            and self._spy_samples >= 101
            and len(self._spy_closes) == 2
            and len(self._spy_sma_values) == 2
            and self._aapl_rsi.IsReady
            and self._aapl_close_samples >= 4
        )

    def _spy_crosses_above_sma(self):
        return (
            self._spy_closes[-2] <= self._spy_sma_values[-2]
            and self._spy_closes[-1] > self._spy_sma_values[-1]
        )

    def _spy_crosses_below_sma(self):
        return (
            self._spy_closes[-2] >= self._spy_sma_values[-2]
            and self._spy_closes[-1] < self._spy_sma_values[-1]
        )

    def _sync_private_lots(self):
        self._strategy_a_lot = max(0, int(self.Portfolio[self._spy].Quantity))
        self._strategy_b_lot = max(0, int(self.Portfolio[self._aapl].Quantity))

