        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self._spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self._aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self._ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self._bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self._aig = self.AddEquity("AIG", Resolution.Daily).Symbol
        self._symbols = [self._spy, self._aapl, self._ibm, self._bac, self._aig]

        self._spy_sma = SimpleMovingAverage(100)
        self._aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self._last_spy_close = None
        self._last_spy_sma = None
        self._last_aapl_close = None
        self._aapl_red_streak = 0

        self._spy_crossed_above = False
        self._spy_crossed_below = False

        self._lots = {"A": 0, "B": 0}
        self._pending = {"A": False, "B": False}

    def OnData(self, data):
        bars = data.Bars

        has_all_bars = all(
            bars.ContainsKey(symbol) and bars[symbol] is not None
            for symbol in self._symbols
        )

        if bars.ContainsKey(self._spy) and bars[self._spy] is not None:
            self._update_spy_state(bars[self._spy])

        if bars.ContainsKey(self._aapl) and bars[self._aapl] is not None:
            self._update_aapl_state(bars[self._aapl])

        if not has_all_bars:
            return

        if not self._spy_sma.IsReady or not self._aapl_rsi.IsReady:
            return

        self._evaluate_sells()
        self._evaluate_buys(bars[self._spy].Close, bars[self._aapl].Close)

    def OnOrderEvent(self, order_event):
        if order_event.Symbol == self._spy:
            slot = "A"
        elif order_event.Symbol == self._aapl:
            slot = "B"
        else:
            return

        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            self._lots[slot] += int(order_event.FillQuantity)
            if self._lots[slot] < 0:
                self._lots[slot] = 0

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self._pending[slot] = False

    def _update_spy_state(self, bar):
        yesterday_close = self._last_spy_close
        yesterday_sma = self._last_spy_sma

        self._spy_sma.Update(bar.EndTime, bar.Close)
        today_sma = self._spy_sma.Current.Value if self._spy_sma.IsReady else None

        self._spy_crossed_above = False
        self._spy_crossed_below = False

        if (
            yesterday_close is not None
            and yesterday_sma is not None
            and today_sma is not None
        ):
            self._spy_crossed_above = (
                yesterday_close <= yesterday_sma and bar.Close > today_sma
            )
            self._spy_crossed_below = (
                yesterday_close >= yesterday_sma and bar.Close < today_sma
            )

        self._last_spy_close = bar.Close
        self._last_spy_sma = today_sma

    def _update_aapl_state(self, bar):
        if self._last_aapl_close is None:
            self._aapl_red_streak = 0
        elif bar.Close < self._last_aapl_close:
            self._aapl_red_streak += 1
        else:
            self._aapl_red_streak = 0

        self._aapl_rsi.Update(bar.EndTime, bar.Close)
        self._last_aapl_close = bar.Close

    def _evaluate_sells(self):
        if (
            self._lots["A"] > 0
            and not self._pending["A"]
            and self._spy_crossed_below
        ):
            self._submit_order("A", self._spy, -self._lots["A"])

        if (
            self._lots["B"] > 0
            and not self._pending["B"]
            and self._aapl_rsi.Current.Value > 60
        ):
            self._submit_order("B", self._aapl, -self._lots["B"])

    def _evaluate_buys(self, spy_close, aapl_close):
        if (
            self._lots["A"] == 0
            and not self._pending["A"]
            and self._spy_crossed_above
        ):
            target_value = self.Portfolio.TotalPortfolioValue * 40 / 100
            quantity = int(target_value / spy_close)
            self._submit_order("A", self._spy, quantity)

        if (
            self._lots["B"] == 0
            and not self._pending["B"]
            and self._aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20000
        ):
            quantity = int(20000 / aapl_close)
            self._submit_order("B", self._aapl, quantity)

    def _submit_order(self, slot, symbol, quantity):
        if quantity == 0:
            return

        self._pending[slot] = True
        ticket = self.MarketOrder(symbol, quantity)

        if ticket is None or ticket.OrderId <= 0:
            self._pending[slot] = False

