            and not self._pending["B"]
            and self._aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20000
        ):
            quantity = int(20000 / aapl_close)
            self._submit_order("B", self._aapl, quantity)

    def _submit_order(self, slot, symbol, quantity):
        if quantity == 0:
            return

        self._pending[slot] = True
        ticket = self.MarketOrder(symbol, quantity)

        if ticket is None or ticket.OrderId <= 0:
            self._pending[slot] = False
