            elif aapl_bar.Close < self.previous_aapl_close:
                next_aapl_red_streak = self.aapl_red_streak + 1
            else:
                next_aapl_red_streak = 0

            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        complete_day = all(
            bars.ContainsKey(symbol) and bars[symbol] is not None
            for symbol in self.subscribed_symbols
        )

        if complete_day and self._ready_to_trade(current_spy_sma):
            self._evaluate_rules(
                spy_bar.Close,
                current_spy_sma,
                aapl_bar.Close,
                next_aapl_red_streak
            )

